// Circuit Breaker — production-quality implementation with sliding window
class CircuitBreaker {
  constructor(fn, options = {}) {
    this.fn = fn;
    this.threshold = options.threshold ?? 5;       // max failures in window
    this.windowSize = options.windowSize ?? 10;    // track last N calls
    this.timeout = options.timeout ?? 10_000;      // ms before HALF_OPEN probe
    this.halfOpenMax = options.halfOpenMax ?? 2;   // probes before deciding

    this.state = 'CLOSED';
    this.window = [];          // circular buffer: true = success, false = fail
    this.nextAttempt = 0;
    this.halfOpenCount = 0;
    this.halfOpenSuccesses = 0;
  }

  get failureCount() {
    return this.window.filter(r => !r).length;
  }

  record(success) {
    this.window.push(success);
    if (this.window.length > this.windowSize) this.window.shift();
  }

  async call(...args) {
    if (this.state === 'OPEN') {
      if (Date.now() < this.nextAttempt) {
        const err = new Error('CircuitBreaker OPEN — fast fail');
        err.code = 'CIRCUIT_OPEN';
        throw err;
      }
      this.state = 'HALF_OPEN';
      this.halfOpenCount = 0;
      this.halfOpenSuccesses = 0;
    }

    try {
      const result = await this.fn(...args);
      this.onSuccess();
      return result;
    } catch (err) {
      this.onFailure();
      throw err;
    }
  }

  onSuccess() {
    this.record(true);
    if (this.state === 'HALF_OPEN') {
      this.halfOpenSuccesses++;
      if (this.halfOpenSuccesses >= this.halfOpenMax) {
        this.state = 'CLOSED';
        this.window = [];  // reset window after recovery
        console.log('[CB] Closed — service recovered');
      }
    }
  }

  onFailure() {
    this.record(false);
    if (this.state === 'HALF_OPEN') {
      this.state = 'OPEN';
      this.nextAttempt = Date.now() + this.timeout;
      console.warn('[CB] Re-opened — probe failed');
      return;
    }
    if (this.failureCount >= this.threshold) {
      this.state = 'OPEN';
      this.nextAttempt = Date.now() + this.timeout;
      console.warn(`[CB] Opened after ${this.failureCount} failures`);
    }
  }
}

