// Orchestration-based Saga — persistent state machine
// Each saga step persists its state before executing (so restarts are safe)

const SagaStatus = {
  STARTED:             'STARTED',
  PAYMENT_RESERVED:    'PAYMENT_RESERVED',
  INVENTORY_RESERVED:  'INVENTORY_RESERVED',
  COMPLETED:           'COMPLETED',
  COMPENSATING:        'COMPENSATING',
  COMPENSATED:         'COMPENSATED',
  FAILED:              'FAILED',
};

class PlaceOrderSaga {
  constructor({ sagaId, order, sagaStore, paymentSvc, inventorySvc, shipmentSvc }) {
    this.sagaId = sagaId;
    this.order = order;
    this.store = sagaStore;        // persistent key-value store
    this.payment = paymentSvc;
    this.inventory = inventorySvc;
    this.shipment = shipmentSvc;
  }

  async execute() {
    await this.store.save(this.sagaId, { status: SagaStatus.STARTED, order: this.order });

    try {
      // Step 1: reserve payment
      const charge = await this.payment.reserve({
        idempotencyKey: `${this.sagaId}-payment`,
        amount: this.order.total,
      });
      await this.store.save(this.sagaId, {
        status: SagaStatus.PAYMENT_RESERVED,
        chargeId: charge.id,
      });

      // Step 2: reserve inventory
      const reservation = await this.inventory.reserve({
        idempotencyKey: `${this.sagaId}-inventory`,
        items: this.order.items,
      });
      await this.store.save(this.sagaId, {
        status: SagaStatus.INVENTORY_RESERVED,
        reservationId: reservation.id,
      });

      // Step 3: create shipment
      await this.shipment.create({
        idempotencyKey: `${this.sagaId}-shipment`,
        address: this.order.address,
        items: this.order.items,
      });
      await this.store.save(this.sagaId, { status: SagaStatus.COMPLETED });
      return { success: true };

    } catch (err) {
      console.error(`[Saga ${this.sagaId}] Step failed:`, err.message);
      await this.compensate();
      return { success: false, reason: err.message };
    }
  }

  async compensate() {
    await this.store.save(this.sagaId, { status: SagaStatus.COMPENSATING });
    const state = await this.store.load(this.sagaId);

    // Compensate in reverse order of steps completed
    if (state.reservationId) {
      await this.inventory.release({
        idempotencyKey: `${this.sagaId}-inv-release`,
        reservationId: state.reservationId,
      });
    }
    if (state.chargeId) {
      await this.payment.refund({
        idempotencyKey: `${this.sagaId}-payment-refund`,
        chargeId: state.chargeId,
      });
    }
    await this.store.save(this.sagaId, { status: SagaStatus.COMPENSATED });
  }
}

