// Event Sourcing + CQRS — write and read sides

// ─── WRITE SIDE: append events, never overwrite ─────────────────
class OrderAggregate {
  constructor(id) {
    this.id = id;
    this.status = null;
    this.items = [];
    this.version = 0;
    this._uncommitted = [];
  }

  // Reconstitute from event history
  static fromHistory(id, events) {
    const agg = new OrderAggregate(id);
    for (const event of events) agg.apply(event);
    return agg;
  }

  // Apply an event to mutate local state
  apply(event) {
    switch (event.type) {
      case 'OrderPlaced':
        this.status = 'placed';
        this.items = event.payload.items;
        break;
      case 'PaymentReserved':
        this.status = 'payment_reserved';
        this.chargeId = event.payload.chargeId;
        break;
      case 'OrderShipped':
        this.status = 'shipped';
        this.trackingId = event.payload.trackingId;
        break;
      case 'OrderCancelled':
        this.status = 'cancelled';
        break;
    }
    this.version++;
  }

  // Raise a new event (validate business rules first)
  placeOrder(items, userId) {
    if (this.status !== null) throw new Error('Order already exists');
    const event = {
      type: 'OrderPlaced',
      aggregateId: this.id,
      version: this.version + 1,
      occurredAt: new Date().toISOString(),
      payload: { items, userId },
    };
    this.apply(event);
    this._uncommitted.push(event);
  }

  shipOrder(trackingId) {
    if (this.status !== 'payment_reserved') {
      throw new Error('Cannot ship — payment not reserved');
    }
    const event = {
      type: 'OrderShipped',
      aggregateId: this.id,
      version: this.version + 1,
      occurredAt: new Date().toISOString(),
      payload: { trackingId },
    };
    this.apply(event);
    this._uncommitted.push(event);
  }

  getUncommittedEvents() {
    return this._uncommitted.splice(0);
  }
}

// ─── Event Store abstraction ─────────────────────────────────────
class InMemoryEventStore {
  constructor() { this.streams = new Map(); }

  async append(aggregateId, events, expectedVersion) {
    const stream = this.streams.get(aggregateId) ?? [];
    // Optimistic concurrency check
    if (stream.length !== expectedVersion) {
      throw new Error(`Concurrency conflict: expected v${expectedVersion}, got v${stream.length}`);
    }
    this.streams.set(aggregateId, [...stream, ...events]);
  }

  async load(aggregateId) {
    return this.streams.get(aggregateId) ?? [];
  }
}

// ─── READ SIDE: projection updated from events ───────────────────
class OrderReadModelProjector {
  constructor(readDb) { this.db = readDb; }

  async handle(event) {
    switch (event.type) {
      case 'OrderPlaced':
        await this.db.upsert('order_views', {
          id: event.aggregateId,
          status: 'placed',
          itemCount: event.payload.items.length,
          userId: event.payload.userId,
          placedAt: event.occurredAt,
        });
        break;
      case 'OrderShipped':
        await this.db.update('order_views', event.aggregateId, {
          status: 'shipped',
          trackingId: event.payload.trackingId,
          shippedAt: event.occurredAt,
        });
        break;
      case 'OrderCancelled':
        await this.db.update('order_views', event.aggregateId, { status: 'cancelled' });
        break;
    }
  }
}

// ─── Usage ───────────────────────────────────────────────────────
const store = new InMemoryEventStore();
const orderId = crypto.randomUUID();

// Place an order
const order = new OrderAggregate(orderId);
order.placeOrder([{ sku: 'BOOK-1', qty: 1 }], 'user-42');
const events = order.getUncommittedEvents();
await store.append(orderId, events, 0);  // v0 → v1

// Later: reconstitute from event log
const history = await store.load(orderId);
const restored = OrderAggregate.fromHistory(orderId, history);
console.log(restored.status);  // 'placed'
console.log(restored.version); // 1
